cd /tmp/probe && python3 - <<'EOF'
import sqlite3, os
for f in ("rich1.db","rich2.db","rich3.db"):
    if os.path.exists(f): os.remove(f)

# rich1: PKs, autoincrement, composite PK, NOT NULL, UNIQUE, DEFAULTs, CHECK
c = sqlite3.connect("rich1.db")
c.executescript("""
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  age INTEGER DEFAULT 18,
  bio TEXT DEFAULT 'hello ''world''',
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  score REAL DEFAULT 1.5,
  active INTEGER DEFAULT 1,
  CONSTRAINT age_check CHECK (age >= 0)
);
CREATE TABLE posts (
  id INTEGER PRIMARY KEY,
  user_id INTEGER NOT NULL,
  title TEXT NOT NULL DEFAULT 'untitled',
  body TEXT,
  UNIQUE (user_id, title)
);
CREATE TABLE composite (
  a INTEGER NOT NULL,
  b TEXT NOT NULL,
  c BLOB,
  PRIMARY KEY (a, b)
);
""")
c.commit(); c.close()

# rich2: FKs with actions, indexes
c = sqlite3.connect("rich2.db")
c.executescript("""
PRAGMA foreign_keys = ON;
CREATE TABLE parent (
  id INTEGER PRIMARY KEY,
  code TEXT UNIQUE
);
CREATE TABLE child (
  id INTEGER PRIMARY KEY,
  parent_id INTEGER REFERENCES parent(id) ON DELETE CASCADE ON UPDATE SET NULL,
  parent_code TEXT,
  FOREIGN KEY (parent_code) REFERENCES parent(code) ON DELETE SET DEFAULT
);
CREATE INDEX idx_child_pid ON child(parent_id);
CREATE UNIQUE INDEX idx_child_code ON child(parent_code);
CREATE INDEX idx_partial ON child(parent_id) WHERE parent_id > 10;
CREATE INDEX idx_expr ON child(parent_id + 1);
CREATE INDEX idx_desc ON child(id DESC);
""")
c.commit(); c.close()

# rich3: views and triggers
c = sqlite3.connect("rich3.db")
c.executescript("""
CREATE TABLE t1 (id INTEGER PRIMARY KEY, val TEXT);
CREATE VIEW v1 AS SELECT id, val FROM t1 WHERE id > 0;
CREATE TRIGGER trg1 AFTER INSERT ON t1 BEGIN UPDATE t1 SET val = NEW.val WHERE id = NEW.id; END;
CREATE VIEW v2(x, y) AS SELECT id, val FROM t1;
""")
c.commit(); c.close()
print("done")
EOF

