  column "id" {
    null = true
    type = integer
  }
  column "code" {
    null = true
    type = text
  }
  primary_key {
    columns = [column.id]
  }
  index "sqlite_autoindex_parent_1" {
    unique  = true
    columns = [column.code]
  }
}
table "child" {
  schema = schema.main
  column "id" {
    null = true
    type = integer
  }
  column "parent_id" {
    null = true
    type = integer
  }
  column "parent_code" {
    null = true
    type = text
