    columns     = [column.parent_code]
    ref_columns = [table.parent.column.code]
    on_update   = NO_ACTION
    on_delete   = SET_DEFAULT
  }
  foreign_key "1" {
    columns     = [column.parent_id]
    ref_columns = [table.parent.column.id]
    on_update   = SET_NULL
    on_delete   = CASCADE
